create type public.discovery_session_status as enum('planned','in-progress','completed','cancelled');
create type public.discovery_finding_status as enum('confirmed','refined','contradicted','unclear');
create table public.discovery_sessions(id uuid primary key default gen_random_uuid(),public_id text not null unique default('disc_'||replace(gen_random_uuid()::text,'-','')),organization_id uuid not null references public.organizations(id),candidate_id uuid not null,assessment_session_id uuid not null,consultant_membership_id uuid not null,status public.discovery_session_status not null default'planned',scheduled_at timestamptz,occurred_at timestamptz,started_at timestamptz,completed_at timestamptz,summary text not null default'',consultant_notes text not null default'',next_steps text not null default'',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(candidate_id,organization_id)references public.candidates(id,organization_id),foreign key(assessment_session_id,organization_id)references public.assessment_sessions(id,organization_id),foreign key(consultant_membership_id,organization_id)references public.organization_memberships(id,organization_id),unique(id,organization_id));
create index discovery_sessions_candidate_idx on public.discovery_sessions(candidate_id,created_at desc);
create table public.discovery_observations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),session_id uuid not null,candidate_id uuid not null,topic_key text not null,topic_label text not null,finding text not null,candidate_statement text not null default'',status public.discovery_finding_status not null,consultant_significance text not null default'',follow_up_needed boolean not null default false,source text not null default'discovery' check(source='discovery'),created_by_membership_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(session_id,organization_id)references public.discovery_sessions(id,organization_id),foreign key(candidate_id,organization_id)references public.candidates(id,organization_id),foreign key(created_by_membership_id,organization_id)references public.organization_memberships(id,organization_id),unique(session_id,topic_key));
create table public.discovery_intelligence(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),session_id uuid not null,candidate_id uuid not null,version integer not null default 1,current_snapshot jsonb not null,brand_strategy_readiness text not null check(brand_strategy_readiness in('in-progress','substantially-complete','ready-for-brand-strategy')),generated_at timestamptz not null default now(),superseded_at timestamptz,foreign key(session_id,organization_id)references public.discovery_sessions(id,organization_id),foreign key(candidate_id,organization_id)references public.candidates(id,organization_id));
create unique index discovery_current_intelligence_idx on public.discovery_intelligence(session_id)where superseded_at is null;
alter table public.discovery_sessions enable row level security;alter table public.discovery_sessions force row level security;alter table public.discovery_observations enable row level security;alter table public.discovery_observations force row level security;alter table public.discovery_intelligence enable row level security;alter table public.discovery_intelligence force row level security;
create policy discovery_sessions_access on public.discovery_sessions for all to authenticated using(public.can_access_candidate(candidate_id))with check(public.can_access_candidate(candidate_id));
create policy discovery_observations_access on public.discovery_observations for all to authenticated using(public.can_access_candidate(candidate_id))with check(public.can_access_candidate(candidate_id));
create policy discovery_intelligence_access on public.discovery_intelligence for select to authenticated using(public.can_access_candidate(candidate_id));
revoke all on public.discovery_sessions,public.discovery_observations,public.discovery_intelligence from anon,authenticated;grant select,insert,update on public.discovery_sessions,public.discovery_observations to authenticated;grant select on public.discovery_intelligence to authenticated;

create function public.discovery_session_payload(sid uuid)returns jsonb language sql security definer set search_path=''as $$select jsonb_build_object('id',s.id,'public_id',s.public_id,'candidate_public_id',c.public_id,'assessment_session_id',s.assessment_session_id,'status',s.status,'summary',s.summary,'consultant_notes',s.consultant_notes,'next_steps',s.next_steps,'started_at',s.started_at,'completed_at',s.completed_at,'created_at',s.created_at,'updated_at',s.updated_at,'assessment_snapshot',a.analysis_snapshot,'observations',coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'topicId',o.topic_key,'topic',o.topic_label,'finding',o.finding,'candidateStatement',o.candidate_statement,'status',o.status,'significance',o.consultant_significance,'followUpNeeded',o.follow_up_needed,'source',o.source,'createdAt',o.created_at,'updatedAt',o.updated_at)order by o.created_at)from public.discovery_observations o where o.session_id=s.id),'[]'::jsonb),'current_intelligence',(select i.current_snapshot from public.discovery_intelligence i where i.session_id=s.id and i.superseded_at is null))from public.discovery_sessions s join public.candidates c on c.id=s.candidate_id join public.assessment_analyses a on a.session_id=s.assessment_session_id and a.superseded_at is null where s.id=sid$$;
create function public.get_or_create_discovery_session(target_candidate_public_id text)returns jsonb language plpgsql security definer set search_path=''as $$declare c public.candidates;s public.discovery_sessions;assessment_id uuid;m uuid;begin select*into c from public.candidates where public_id=target_candidate_public_id and public.can_access_candidate(id);if c.id is null then raise exception'candidate unavailable'using errcode='42501';end if;select x.id into assessment_id from public.assessment_sessions x where x.candidate_id=c.id and x.status='analyzed'order by x.completed_at desc limit 1;if assessment_id is null then raise exception'assessment required';end if;select*into s from public.discovery_sessions where candidate_id=c.id and status in('planned','in-progress','completed')order by created_at desc limit 1;if s.id is null then m:=public.current_active_membership_id(c.organization_id);insert into public.discovery_sessions(organization_id,candidate_id,assessment_session_id,consultant_membership_id)values(c.organization_id,c.id,assessment_id,m)returning*into s;end if;return public.discovery_session_payload(s.id);end$$;
create function public.save_discovery_observation(target_candidate_public_id text,topic_key text,topic_label text,finding_text text,candidate_statement_text text,finding_status public.discovery_finding_status,consultant_significance text,follow_up_needed boolean)returns void language plpgsql security definer set search_path=''as $$declare payload jsonb;sid uuid;cid uuid;org uuid;m uuid;begin payload:=public.get_or_create_discovery_session(target_candidate_public_id);sid:=(payload->>'id')::uuid;select candidate_id,organization_id into cid,org from public.discovery_sessions where id=sid;m:=public.current_active_membership_id(org);insert into public.discovery_observations(organization_id,session_id,candidate_id,topic_key,topic_label,finding,candidate_statement,status,consultant_significance,follow_up_needed,created_by_membership_id)values(org,sid,cid,topic_key,topic_label,finding_text,candidate_statement_text,finding_status,consultant_significance,follow_up_needed,m)on conflict(session_id,topic_key)do update set topic_label=excluded.topic_label,finding=excluded.finding,candidate_statement=excluded.candidate_statement,status=excluded.status,consultant_significance=excluded.consultant_significance,follow_up_needed=excluded.follow_up_needed,updated_at=now();update public.discovery_sessions set status='in-progress',started_at=coalesce(started_at,now()),updated_at=now()where id=sid;end$$;
create function public.save_discovery_notes(target_candidate_public_id text,summary_text text,consultant_notes_text text,next_steps_text text)returns void language plpgsql security definer set search_path=''as $$declare payload jsonb;begin payload:=public.get_or_create_discovery_session(target_candidate_public_id);update public.discovery_sessions set summary=summary_text,consultant_notes=consultant_notes_text,next_steps=next_steps_text,status=case when status='planned'then'in-progress'::public.discovery_session_status else status end,started_at=coalesce(started_at,now()),updated_at=now()where id=(payload->>'id')::uuid;end$$;
create function public.complete_discovery_session(target_candidate_public_id text,intelligence_snapshot jsonb,brand_strategy_readiness text)returns void language plpgsql security definer set search_path=''as $$declare payload jsonb;sid uuid;cid uuid;org uuid;begin payload:=public.get_or_create_discovery_session(target_candidate_public_id);sid:=(payload->>'id')::uuid;select candidate_id,organization_id into cid,org from public.discovery_sessions where id=sid;update public.discovery_intelligence set superseded_at=now()where session_id=sid and superseded_at is null;insert into public.discovery_intelligence(organization_id,session_id,candidate_id,current_snapshot,brand_strategy_readiness)values(org,sid,cid,intelligence_snapshot,brand_strategy_readiness);update public.discovery_sessions set status='completed',completed_at=now(),occurred_at=coalesce(occurred_at,now()),updated_at=now()where id=sid;end$$;
revoke all on function public.discovery_session_payload(uuid),public.get_or_create_discovery_session(text),public.save_discovery_observation(text,text,text,text,text,public.discovery_finding_status,text,boolean),public.save_discovery_notes(text,text,text,text),public.complete_discovery_session(text,jsonb,text)from public;grant execute on function public.get_or_create_discovery_session(text),public.save_discovery_observation(text,text,text,text,text,public.discovery_finding_status,text,boolean),public.save_discovery_notes(text,text,text,text),public.complete_discovery_session(text,jsonb,text)to authenticated;
create function public.prevent_discovery_provenance_change()returns trigger language plpgsql set search_path=''as $$begin if new.organization_id<>old.organization_id or new.candidate_id<>old.candidate_id or new.session_id<>old.session_id then raise exception'Discovery provenance is immutable'using errcode='55000';end if;return new;end$$;
create trigger discovery_observation_provenance before update on public.discovery_observations for each row execute function public.prevent_discovery_provenance_change();
